CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Conversations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "SessionId" text NOT NULL,
    "Title" text NOT NULL,
    "CreatedUtc" timestamp without time zone NOT NULL,
    "UpdatedUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Conversations" PRIMARY KEY ("Id")
);

CREATE TABLE "FileItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    "Description" text,
    "MetaType" text,
    "IsDeleted" boolean NOT NULL,
    "CreatedByUserId" text NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "FileSize" bigint NOT NULL,
    "FilePath" text,
    "ChunkId" bigint,
    CONSTRAINT "PK_FileItems" PRIMARY KEY ("Id")
);

CREATE TABLE "KnowledgeBaseCategories" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "CreatedByUserId" text NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "UpdatedByUserId" text,
    "LastModifiedDate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_KnowledgeBaseCategories" PRIMARY KEY ("Id")
);

CREATE TABLE "KnowledgeBases" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "ServiceAgentId" bigint NOT NULL,
    "CreatedByUserId" text NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "UpdatedByUserId" text,
    "LastModifiedDate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_KnowledgeBases" PRIMARY KEY ("Id")
);

CREATE TABLE "LlmProviders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_LlmProviders" PRIMARY KEY ("Id")
);

CREATE TABLE "MenuItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(200) NOT NULL,
    "Category" character varying(100) NOT NULL,
    "Description" text NOT NULL,
    "Price" numeric(10,2) NOT NULL,
    "IsAvailable" boolean NOT NULL,
    CONSTRAINT "PK_MenuItems" PRIMARY KEY ("Id")
);

CREATE TABLE "RestaurantTables" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Number" integer NOT NULL,
    "Seats" integer NOT NULL,
    "Location" character varying(50) NOT NULL,
    CONSTRAINT "PK_RestaurantTables" PRIMARY KEY ("Id")
);

CREATE TABLE "TelegramConversations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TelegramUserId" bigint NOT NULL,
    "TelegramUserGuid" text NOT NULL,
    "SessionId" text NOT NULL,
    "CreatedUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_TelegramConversations" PRIMARY KEY ("Id")
);

CREATE TABLE "Turns" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ConversationId" bigint NOT NULL,
    "Index" integer NOT NULL,
    "Question" text NOT NULL,
    "Answer" text NOT NULL,
    "RetrievedChunkIds" text[] NOT NULL,
    "CreatedUtc" timestamp without time zone NOT NULL,
    "QuestionDate" timestamp without time zone NOT NULL,
    "AnswerDate" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Turns" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Turns_Conversations_ConversationId" FOREIGN KEY ("ConversationId") REFERENCES "Conversations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "KnowledgeBaseDocuments" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CreatedByUserId" text NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "UpdatedByUserId" text,
    "LastModifiedDate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    "DocId" text,
    "VectorStoreSyncDate" timestamp without time zone,
    "FileItemId" bigint NOT NULL,
    "KnowledgeBaseId" bigint NOT NULL,
    "KnowledgeBaseCategoryId" bigint NOT NULL,
    CONSTRAINT "PK_KnowledgeBaseDocuments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_KnowledgeBaseDocuments_FileItems_FileItemId" FOREIGN KEY ("FileItemId") REFERENCES "FileItems" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_KnowledgeBaseDocuments_KnowledgeBaseCategories_KnowledgeBas~" FOREIGN KEY ("KnowledgeBaseCategoryId") REFERENCES "KnowledgeBaseCategories" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_KnowledgeBaseDocuments_KnowledgeBases_KnowledgeBaseId" FOREIGN KEY ("KnowledgeBaseId") REFERENCES "KnowledgeBases" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ServiceAgents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "APIToken" text NOT NULL,
    "LlmProviderId" integer NOT NULL,
    "ModelName" text NOT NULL,
    "SystemPrompt" text NOT NULL,
    "CreatedByUserId" text NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "UpdatedByUserId" text,
    "LastModifiedDate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    "IsEnabled" boolean NOT NULL,
    CONSTRAINT "PK_ServiceAgents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ServiceAgents_LlmProviders_LlmProviderId" FOREIGN KEY ("LlmProviderId") REFERENCES "LlmProviders" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Bookings" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TableId" bigint NOT NULL,
    "CustomerName" character varying(200) NOT NULL,
    "Phone" character varying(50) NOT NULL,
    "Guests" integer NOT NULL,
    "StartTime" timestamp without time zone NOT NULL,
    "EndTime" timestamp without time zone NOT NULL,
    "Notes" text,
    "Status" character varying(20) NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Bookings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Bookings_RestaurantTables_TableId" FOREIGN KEY ("TableId") REFERENCES "RestaurantTables" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Feedbacks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TurnId" bigint NOT NULL,
    "Value" integer NOT NULL,
    "SetUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Feedbacks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Feedbacks_Turns_TurnId" FOREIGN KEY ("TurnId") REFERENCES "Turns" ("Id") ON DELETE CASCADE
);

